func:
// 양액 직접 제어 — MQTT payload { channel, on, autoOffSec } → Modbus FC5 single coil
// 안전 인터락: safetyStop 활성 시 거부.
// dead-man timer: payload.autoOffSec > 0 일 때만 자동 OFF 예약 (0 = 비활성, 사용자가 명시적으로 끌 때까지 ON).

const payload = msg.payload || {};
const { channel, on } = payload;
const autoOffSec = Number(payload.autoOffSec) || 0;

if (typeof channel !== 'number' || channel < 0 || channel > 31) {
    node.warn('direct-relay: 잘못된 channel ' + channel);
    return null;
}
if (typeof on !== 'boolean') {
    node.warn('direct-relay: 잘못된 on ' + on);
    return null;
}

// 안전 인터락 — direct 제어도 안전 stop 적용
if (global.get('safetyStop')) {
    node.warn(`direct-relay 거부: safetyStop 활성 (CH${channel} ${on ? 'ON' : 'OFF'})`);
    node.status({ fill: 'red', shape: 'ring', text: '안전 정지 — 거부' });
    return null;
}

// 사이클 진행 중이면 거부 (자동/수동 cycle 과 충돌 방지)
if (global.get('cycleInProgress')) {
    node.warn(`direct-relay 거부: 사이클 진행 중 (CH${channel} ${on ? 'ON' : 'OFF'})`);
    node.status({ fill: 'yellow', shape: 'ring', text: '사이클 중 — 거부' });
    return null;
}

// dead-man timer — autoOffSec > 0 일 때만 자동 OFF 예약 (해당 채널만)
const timers = global.get('directRelayTimers') || {};
if (timers[channel]) {
    clearTimeout(timers[channel]);
    delete timers[channel];
}
if (on && autoOffSec > 0) {
    timers[channel] = setTimeout(() => {
        node.warn(`dead-man timer: CH${channel} ${autoOffSec}초 경과 자동 OFF`);
        node.send([{
            payload: {
                value: false,
                fc: 5, unitid: 3,
                address: channel,
                quantity: 1,
            },
            label: `[dead-man] CH${channel} OFF`,
        }, null]);
        // relayStatus 갱신
        const status = global.get('directRelayStatus') || {};
        status[channel] = false;
        global.set('directRelayStatus', status);
        const t = global.get('directRelayTimers') || {};
        delete t[channel];
        global.set('directRelayTimers', t);
    }, autoOffSec * 1000);
}
global.set('directRelayTimers', timers);

// relayStatus 갱신 (UI 가 추후 사용)
const status = global.get('directRelayStatus') || {};
status[channel] = on;
global.set('directRelayStatus', status);

node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: `CH${channel} ${on ? 'ON' : 'OFF'}` });
node.log(`direct-relay: CH${channel} ${on ? 'ON' : 'OFF'}` + (on && autoOffSec > 0 ? ` (${autoOffSec}초 후 자동 OFF)` : ''));

// modbus-flex-write 호환
return {
    payload: {
        value: on,
        fc: 5,        // FC5 = Write Single Coil
        unitid: 3,    // Unit-Id 3 = 32CH 통합 릴레이
        address: channel,
        quantity: 1,
    },
    label: `direct CH${channel} ${on ? 'ON' : 'OFF'}`,
};
